 import { Group, Mesh, CylinderGeometry, CircleGeometry, PlaneGeometry, PointLight, SpotLight, Vector3 } from 'three/webgpu';
import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, mul, add, sub } from 'three/tsl';
import { gsap } from 'gsap';
import { registerOrbitDrag } from '@/primitives';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  const root = new ctx.THREE.Group();
  group.add(root);

  const THREE = ctx.THREE;

  // --- Backdrop gradient plane (7x6 at z=-2.5) ---
  const stops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 0.55, hex: '#101017' },
    { at: 1, hex: '#16161d' },
  ];
  const c0 = new THREE.Color(stops[0].hex);
  const c1 = new THREE.Color(stops[1].hex);
  const c2 = new THREE.Color(stops[2].hex);

  const gradColor = mix(
    mix(vec3(c0.r, c0.g, c0.b), vec3(c1.r, c1.g, c1.b), smoothstep(0.0, 0.55, uv().y)),
    vec3(c2.r, c2.g, c2.b),
    smoothstep(0.55, 1.0, uv().y)
  );

  const backdropGeo = new THREE.PlaneGeometry(7, 6);
  const backdropMat = new MeshStandardNodeMaterial({ color: gradColor, roughness: 1.0, metalness: 0.0 });
  const backdrop = new THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // --- Plinth ---
  const plinthGeo = new THREE.CylinderGeometry(1.4, 1.4, 0.25, 64);
  const plinthMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(config.intent?.visualSpec?.colors?.surface ?? '#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new THREE.Mesh(plinthGeo, plinthMat);
  plinth.position.y = -1.1 - 0.125;
  plinth.castShadow = true;
  plinth.receiveShadow = true;
  root.add(plinth);

  // --- Contact shadow ---
  const shadowGeo = new THREE.CircleGeometry(1.6, 64);
  const shadowMat = new MeshStandardNodeMaterial({
    color: new THREE.Color(0x000000),
    transparent: true,
    opacity: 0.55,
    roughness: 1,
    metalness: 0,
  });
  const shadow = new THREE.Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.y = -1.225 - 0.01;
  root.add(shadow);

  // --- Lights ---
  const keyLight = new THREE.SpotLight(new THREE.Color('#ffffff'), 1.2);
  keyLight.position.set(3, 4, 5);
  keyLight.angle = Math.PI / 5;
  keyLight.penumbra = 0.25;
  keyLight.castShadow = true;
  root.add(keyLight);

  const rimLight = new THREE.SpotLight(new THREE.Color('#ff2a38'), 1.0);
  rimLight.position.set(-4, 2, 3);
  rimLight.angle = Math.PI / 6;
  rimLight.penumbra = 0.35;
  rimLight.target.position.set(0, -0.2, 0);
  root.add(rimLight);
  root.add(rimLight.target);

  const fillLight = new THREE.PointLight(new THREE.Color('#e8ecf2'), 0.4);
  fillLight.position.set(0, 3, -2);
  root.add(fillLight);

  // --- Watch GLB ---
  const heroGroup = new ctx.THREE.Group();
  root.add(heroGroup);

  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const watchScene = gltf.scene;
    watchScene.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        if (child.material && child.material.isMeshStandardMaterial) {
          child.material.roughness = 0.52;
          child.material.metalness = 0.55;
          child.material.clearcoat = 0.2;
          child.material.clearcoatRoughness = 0.4;
          child.material.anisotropy = 0.8;
          if (child.material.emissive) {
            const emissiveColor = child.material.emissive.clone();
            child.material.emissiveIntensity = Math.min(1.6, child.material.emissiveIntensity);
          }
        } else if (child.material) {
          const oldMap = child.material.map;
          const newMat = new MeshStandardNodeMaterial({
            map: oldMap,
            color: child.material.color ?? new THREE.Color('#e8ecf2'),
            roughness: 0.52,
            metalness: 0.55,
            clearcoat: 0.2,
            clearcoatRoughness: 0.4,
            anisotropy: 0.8,
          });
          child.material = newMat;
        }
      }
    });
    // Normalize to 2.2 units tall, centered
    const box = new THREE.Box3().setFromObject(watchScene);
    const size = box.getSize(new THREE.Vector3());
    const scale = size.y > 0 ? 2.2 / size.y : 1;
    watchScene.scale.setScalar(scale);
    const center = box.getCenter(new THREE.Vector3());
    watchScene.position.set(-center.x * scale, (-box.min.y * scale) - 1.1 + 1.1, -center.z * scale);
    heroGroup.add(watchScene);
  });

  // --- Text ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of textItems) {
    const opts = { color: item.color ?? '#e8ecf2', align: 'center' };
    if (item.typography?.fontSize) opts.fontSize = item.typography.fontSize;
    const label = ctx.fontAtlas.createText(String(item.text), opts);
    let y = 0;
    switch (item.role) {
      case 'headline':
        y = -1.5;
        break;
      case 'body':
        y = -2.0;
        break;
      case 'caption':
      default:
        y = -2.35;
        break;
    }
    label.position.set(0, y, 0.5);
    root.add(label);
  }

  // --- Cinematic primitives ---
  let orbitResult = null;
  let depthResult = null;

  const primitives = config.cinematicPrimitives ?? [];
  for (const p of primitives) {
    if (p.name === 'orbit') {
      orbitResult = ctx.primitives['orbit'](heroGroup, p.params ?? { speed: 0.15, radius: 0.6 });
    }
    if (p.name === 'depth-rotate') {
      depthResult = ctx.primitives['depth-rotate'](heroGroup, p.params ?? { maxDeg: 6 });
    }
  }

  // --- Hover depth-rotate fallback if primitive not registered ---
  if (!depthResult) {
    group.userData.handlers = group.userData.handlers || {};
    group.userData.handlers.onPointerMove = (e) => {
      const x = (e.normalized.x - 0.5) * 6;
      const y = (e.normalized.y - 0.5) * 4;
      gsap.to(heroGroup.rotation, {
        x: y * (6 * Math.PI / 180),
        y: x * (6 * Math.PI / 180) + (orbitResult ? orbitResult.timeline?.progress() * 0.3 : 0),
        duration: 0.3,
        ease: 'cubic-bezier(0.215,0.61,0.355,1)',
      });
    };
    group.userData.handlers.onPointerLeave = () => {
      gsap.to(heroGroup.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.15, ease: 'power1.out' });
      gsap.to(heroGroup.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.9,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        delay: 0.15,
      });
      gsap.to(heroGroup.rotation, { x: 0, y: 0, duration: 0.6, ease: 'power3.out' });
    };
  }

  // --- Cleanup ---
  group.userData.cleanup = () => {
    if (orbitResult?.cleanup) orbitResult.cleanup();
    if (depthResult?.cleanup) depthResult.cleanup();
    gsap.killTweensOf(heroGroup);
    gsap.killTweensOf(heroGroup.scale);
    gsap.killTweensOf(heroGroup.rotation);
    backdropGeo.dispose();
    backdropMat.dispose();
    plinthGeo.dispose();
    plinthMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    heroGroup.traverse((o) => {
      if (o.isMesh) {
        o.geometry?.dispose();
        o.material?.dispose();
      }
    });
  };

  return group;
}
